479		if !errors.Is(err, ErrInvalidSnapshot) || !strings.Contains(err.Error(), "height 1") {
480			t.Fatalf("err=%v, want ErrInvalidSnapshot naming height 1", err)
481		}
482		requireUnchanged(t, index, blocks, byHash, tip)
483	}
