485	func TestRestorePreservesTxIdentifiersVerbatim(t *testing.T) {
486		// Empty and duplicated identifiers and their order survive a restore,
487		// and a first-block parent of "" is a valid chain-start marker.
488		input := `{"version":1,"tip":2,"blocks":[` +
489			`{"height":1,"hash":"h1","parent":"","txs":["","a",""]},` +
490			`{"height":2,"hash":"h2","parent":"h1","txs":["a","a"]}` +
491			`]}`
