494			t.Fatalf("restore failed: %v", err)
495		}
496		if got := index.Blocks[1].Txs; !reflect.DeepEqual(got, []string{"", "a", ""}) {
497			t.Fatalf("height 1 txs=%q", got)
498		}
499		if got := index.Blocks[2].Txs; !reflect.DeepEqual(got, []string{"a", "a"}) {
