507	// errReader fails after delivering a valid snapshot prefix.
508	type errReader struct {
509		data []byte
510		err  error
511	}
512	
513	func (r *errReader) Read(p []byte) (int, error) {
514		if len(r.data) == 0 {
515			return 0, r.err
516		}
517		n := copy(p, r.data)
518		r.data = r.data[n:]
519		return n, nil
520	}
