package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
)

type scriptedReader struct {
	parts []struct {
		n   int
		err error
	}
	data []byte
	off  int
}

func (r *scriptedReader) Read(p []byte) (int, error) {
	if len(r.parts) == 0 {
		return 0, io.EOF
	}
	next := r.parts[0]
	r.parts = r.parts[1:]
	n := copy(p, r.data[r.off:])
	if next.n >= 0 {
		if n > next.n {
			n = next.n
		}
	}
	r.off += n
	return n, next.err
}

func run(name, data string, parts []struct {
	n   int
	err error
}) {
	r := &scriptedReader{data: []byte(data)}
	for _, p := range parts {
		r.parts = append(r.parts, p)
	}
	dec := json.NewDecoder(r)
	for {
		tok, err := dec.Token()
		fmt.Printf("[%s] tok=%T(%v) err=%v\n", name, tok, tok, err)
		if err != nil {
			fmt.Printf("    isEOF=%v isUnexpectedEOF=%v syntax=%T\n",
				errors.Is(err, io.EOF), errors.Is(err, io.ErrUnexpectedEOF), errors.Unwrap(err))
			var se *json.SyntaxError
			fmt.Printf("    asSyntax=%v\n", errors.As(err, &se))
			return
		}
	}
}

func main() {
	half := `{"version":1,"tip":`
	// 1. half doc, clean EOF
	run("half+cleanEOF", half, []struct {
		n   int
		err error
	}{{-1, nil}, {0, io.EOF}})
	// 2. half doc, reader returns ErrUnexpectedEOF
	run("half+UEOF", half, []struct {
		n   int
		err error
	}{{-1, nil}, {0, io.ErrUnexpectedEOF}})
	// 3. half doc, wrapped ErrUnexpectedEOF
	run("half+wrappedUEOF", half, []struct {
		n   int
		err error
	}{{-1, nil}, {0, fmt.Errorf("network: %w", io.ErrUnexpectedEOF)}})
	// 4. valid bytes + ErrUnexpectedEOF in the SAME read, bytes insufficient
	run("bytesAndErrSameRead", half, []struct {
		n   int
		err error
	}{{len(half), io.ErrUnexpectedEOF}})
	// 5. empty input, clean EOF
	run("empty+cleanEOF", "", []struct {
		n   int
		err error
	}{{0, io.EOF}})
	// 6. whitespace only, clean EOF
	run("ws+cleanEOF", "  \n", []struct {
		n   int
		err error
	}{{-1, nil}, {0, io.EOF}})
	// 7. complete doc then clean EOF with whitespace pending
	complete := `{"version":1,"tip":0,"blocks":[]} `
	run("complete+ws+cleanEOF", complete, []struct {
		n   int
		err error
	}{{-1, nil}, {0, io.EOF}})
	// 8. half doc, custom non-EOF error
	run("half+customErr", half, []struct {
		n   int
		err error
	}{{-1, nil}, {0, errors.New("boom")}})
}
