// json decoder matters because the decoder may consume such an error while
// turning the buffered prefix into an end-of-input signal, or hide an error
// delivered together with usable bytes.
type snapshotReadFaultReader struct {
	r     io.Reader
	fault error
}

func (s *snapshotReadFaultReader) Read(p []byte) (int, error) {
	n, err := s.r.Read(p)
	if err != nil && err != io.EOF && s.fault == nil {
