package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
)

type oneShot struct {
	data []byte
	err  error
}

func (r *oneShot) Read(p []byte) (int, error) {
	if len(r.data) == 0 {
		return 0, io.EOF
	}
	n := copy(p, r.data)
	r.data = r.data[n:]
	if n > 0 {
		return n, r.err
	}
	return 0, io.EOF
}

func main() {
	for _, tc := range []struct {
		name string
		doc  string
	}{
		{"complete+ws", `{"version":1,"tip":0,"blocks":[]} `},
		{"complete", `{"version":1,"tip":0,"blocks":[]}`},
	} {
		dec := json.NewDecoder(&oneShot{data: []byte(tc.doc), err: io.ErrUnexpectedEOF})
		for {
			tok, err := dec.Token()
			if err != nil {
				fmt.Printf("[%s] err=%v isUEOF=%v isEOF=%v\n", tc.name, err,
					errors.Is(err, io.ErrUnexpectedEOF), errors.Is(err, io.EOF))
				break
			}
			_ = tok
		}
	}
}
EOF
