package indexroom

import (
	"errors"
	"io"
	"testing"
)

// Temporary edge probes.
func TestTmpEdgeRecoveryAndCompleteWithFault(t *testing.T) {
	full := []byte(`{"version":1,"tip":1,"blocks":[{"height":1,"hash":"h1","parent":"g","txs":[]}]}`)
	cut := 20
	prefix, suffix := full[:cut], full[cut:]

	// Fault on the partial read, then the stream recovers and delivers the
	// rest: restore must succeed.
	idx := New()
	err := idx.Restore(&scriptedSnapshotReader{
		data: full,
		steps: []readStep{
			{cut, io.ErrUnexpectedEOF},
			{len(suffix), nil},
			{-1, io.EOF},
		},
	})
	if err != nil {
		t.Fatalf("recovered stream: err=%v, want nil", err)
	}
	if idx.Tip != 1 || idx.Blocks[1].Hash != "h1" {
		t.Fatalf("chain not restored after recovery: %+v", idx)
	}

	// Complete document (no trailing bytes) and a fault in the same read:
	// success, fault discarded once the document is whole.
	idx2 := New()
	err = idx2.Restore(&scriptedSnapshotReader{
		data: full,
		steps: []readStep{{len(full), errors.New("late connection close")}},
	})
	if err != nil {
		t.Fatalf("complete doc + same-read fault: err=%v, want nil", err)
	}

	// Trailing garbage and a fault together: content verdict wins.
	idx3 := txChain(t, []string{"a"})
	bad := append(append([]byte{}, full...), ' ', 'x')
	err = idx3.Restore(&scriptedSnapshotReader{
		data: bad,
		steps: []readStep{{len(bad), errors.New("boom")}, {0, errors.New("boom")}},
	})
	if !errors.Is(err, ErrInvalidSnapshot) {
		t.Fatalf("trailing garbage: err=%v, want ErrInvalidSnapshot", err)
	}

	_ = prefix
}
EOF
